#[test]
fn charge_and_energy_are_the_files_last_values_not_a_sum_over_the_rows() {
    let dir = scratch("charge");
    // An hour between the rows, as across a pause: the rows alone would make
    // this 1 Ah and 5 Wh; the recording says it did not count that time.
    let path = write_csv(
        &dir,
        "run.csv",
        &[
            row(0, 5.0, 1.0, 0.001, 0.005),
            row(3_600_000, 5.0, 1.0, 0.002, 0.01),
        ],
    );
    let s = opened(recording_file::open_csv(&path, &mut silent())).summary();
    assert_eq!(s.stats.charge_ah, 0.002);
    assert_eq!(s.stats.energy_wh, 0.01);
}

#[test]
fn charge_and_energy_come_from_the_last_good_row() {
    let dir = scratch("charge-last-good");
    let path = write_csv(
        &dir,
        "run.csv",
        &[
            row(0, 5.0, 1.0, 0.001, 0.005),
            row(100, 5.0, 1.0, 0.002, 0.01),
            // Damaged, with a charge of its own that must not count.
            "0:00:00.200,,,1,0.6,0.01,1.68,0,,7,7,".to_string(),
        ],
    );
    let s = opened(recording_file::open_csv(&path, &mut silent())).summary();
    assert_eq!(s.skipped, 1);
    assert_eq!((s.stats.charge_ah, s.stats.energy_wh), (0.002, 0.01));
}

#[test]
fn without_charge_columns_charge_and_energy_are_integrated_from_the_rows() {
    let dir = scratch("integrated");
    let path = write_csv(
        &dir,
        "run.csv",
        &[
            "0:00:00.000,,5,2,0.6,0.01,1.68,0,,,,".to_string(),
            "1:00:00.000,,5,2,0.6,0.01,1.68,0,,,,".to_string(),
        ],
    );
    let s = opened(recording_file::open_csv(&path, &mut silent())).summary();
    near(s.stats.charge_ah, 2.0, "charge");
    near(s.stats.energy_wh, 10.0, "energy");
}

// ---- AC-AXHK2S.3: refusals in plain words ----

#[test]
fn a_wrong_header_is_refused_in_plain_words() {
    let dir = scratch("wrong-header");
    let path = dir.join("run.csv");
    std::fs::write(&path, "time,voltage\n0,5\n").expect("file");
    let why = refused(recording_file::open_csv(&path, &mut silent()));
    assert!(why.to_lowercase().contains("header"), "{why}");
}

#[test]
fn a_binary_file_is_refused_in_plain_words() {
    let dir = scratch("binary");
    let path = dir.join("run.csv");
    std::fs::write(&path, b"\x89PNG\r\n\x1a\n\xff\xfe\x00\x80").expect("file");
    let why = refused(recording_file::open_csv(&path, &mut silent()));
    assert!(why.to_lowercase().contains("text"), "{why}");
}

#[test]
fn an_empty_file_is_refused_in_plain_words() {
    let dir = scratch("empty");
    let path = dir.join("run.csv");
    std::fs::write(&path, "").expect("file");
    let why = refused(recording_file::open_csv(&path, &mut silent()));
    assert!(why.to_lowercase().contains("empty"), "{why}");
}

#[test]
fn a_binary_file_of_any_other_extension_is_refused() {
    let dir = scratch("other-extension");
    let path = dir.join("run.bin");
    std::fs::write(&path, b"\xff\xfe\x00\x80").expect("file");
    refused(recording_file::open(&path, &mut silent()));
}

#[test]
fn a_file_that_is_gone_is_refused_and_not_created() {
    let dir = scratch("gone");
    for name in ["gone.csv", "gone.db"] {
        let path = dir.join(name);
        refused(recording_file::open(&path, &mut silent()));
        assert!(!path.exists(), "{name} was created");
    }
}

// ---- AC-AXHK2S.4: large files, progress and Cancel ----

#[test]
fn the_row_limit_is_ten_million() {
    assert_eq!(MAX_ROWS, 10_000_000);
}

#[test]
fn a_file_past_the_limit_opens_with_its_first_rows_and_says_how_many_were_left_out() {
    let dir = scratch("limit");
    let path = write_csv(&dir, "run.csv", &steady_rows(12));
    let file = opened(recording_file::open_csv_limited(&path, &mut silent(), 5));
    let s = file.summary();
    assert_eq!((s.rows, s.left_out), (5, 7));
    assert_eq!(file.records().len(), 5);
    assert_eq!(s.stats.samples, 5);
    assert_eq!(s.stats.elapsed_ms, 4);
}

#[test]
fn a_file_of_exactly_the_limit_leaves_nothing_out() {
    let dir = scratch("limit-exact");
    let path = write_csv(&dir, "run.csv", &steady_rows(5));
    let s = opened(recording_file::open_csv_limited(&path, &mut silent(), 5)).summary();
    assert_eq!((s.rows, s.left_out), (5, 0));
}

#[test]
fn a_large_file_streams_with_rising_progress_up_to_its_end() {
    let dir = scratch("large");
    let path = write_csv(&dir, "run.csv", &steady_rows(200_000));
    let seen: Arc<Mutex<Vec<(u64, u64)>>> = Arc::default();
    let log = Arc::clone(&seen);
    let mut control = OpenControl {
        cancel: Arc::new(AtomicBool::new(false)),
        progress: Box::new(move |p: OpenProgress| {
            log.lock().expect("log").push((p.done, p.total));
        }),
    };

    let file = opened(recording_file::open_csv(&path, &mut control));

    assert_eq!(file.summary().rows, 200_000);
    let seen = seen.lock().expect("log");
    assert!(seen.len() >= 3, "only {} reports", seen.len());
    assert!(seen.is_sorted_by_key(|p| p.0), "progress went back");
    assert!(seen.iter().all(|&(done, total)| done <= total));
    let &(done, total) = seen.last().expect("a report");
    assert_eq!(done, total, "the last report is the end of the file");
    assert!(total > 0);

    let buckets = file.range(&[Series::Vbus], 0, 199_999, 512);
    assert!(buckets[0].buckets.len() <= 512);
    assert!(!buckets[0].buckets.is_empty());
}

#[test]
fn a_set_cancel_flag_stops_an_open_before_it_starts() {
    let dir = scratch("cancel-first");
    let path = write_csv(&dir, "run.csv", &steady_rows(10));
    let mut control = OpenControl {
        cancel: Arc::new(AtomicBool::new(true)),
        progress: Box::new(|_| {}),
    };
    assert!(is_cancelled(recording_file::open_csv(&path, &mut control)));
}

/// Open `open` on its own thread as the app does, and press Cancel at the
/// first progress report: it must stop the open, not wait for its end.
fn cancel_at_first_report(
    open: impl FnOnce(&mut OpenControl) -> Result<OpenedFile, FileError> + Send + 'static,
) -> bool {
    let cancel = Arc::new(AtomicBool::new(false));
    let (reported, on_report) = mpsc::channel();
    let (resume, on_resume) = mpsc::channel::<()>();
    let mut control = OpenControl {
        cancel: Arc::clone(&cancel),
        progress: Box::new(move |_| {
            let _ = reported.send(());
            let _ = on_resume.recv();
        }),
    };
    let opening = std::thread::spawn(move || open(&mut control));
    on_report.recv().expect("a progress report");
    cancel.store(true, Ordering::SeqCst);
    drop(resume);
    is_cancelled(opening.join().expect("no panic"))
}

#[test]
fn cancel_stops_a_csv_open_in_the_middle() {
    let dir = scratch("cancel-csv");
    let path = write_csv(&dir, "run.csv", &steady_rows(200_000));
    assert!(cancel_at_first_report(move |control| {
        recording_file::open_csv(&path, control)
    }));
}

