#[test]
fn a_vendor_db_opens_like_the_csv_of_the_same_rows() {
    let dir = scratch("vendor-db");
    let rows = three_rows();
    let db = dir.join("run.db");
    vendor_db(&db, TABLE, &rows);
    let csv = write_csv(
        &dir,
        "run.csv",
        &[
            row(0, 5.0, 1.0, 0.0, 0.0),
            row(100, 5.5, 1.0, 0.01, 0.05),
            row(200, 6.0, 1.0, 0.02, 0.11),
        ],
    );

    let from_db = opened(recording_file::open_db(&db, &mut silent()));
    let from_csv = opened(recording_file::open_csv(&csv, &mut silent()));
    let (s, want) = (from_db.summary(), from_csv.summary());

    assert_eq!(s.name, "run.db");
    assert_eq!((s.rows, s.skipped, s.left_out), (3, 0, 0));
    assert_eq!(s.stats, want.stats);
    let lines = |f: &OpenedFile| -> Vec<(u32, i32, i32, f64, f64)> {
        f.records()
            .iter()
            .map(|r| (r.time_ms(), r.vbus_uv(), r.ibus_ua(), r.cc1_v(), r.dp_v()))
            .collect()
    };
    assert_eq!(lines(&from_db), lines(&from_csv));

    let buckets = from_db.range(&[Series::Vbus], 0, 200, 10);
    let max = buckets[0].buckets.iter().map(|b| b.max).fold(0.0, f32::max);
    assert_eq!(max, 6.0);
}

