// ---- AC-AXHK2S.6: export to the vendor layout ----

type StoreRow = (QueueRecord, bool, Option<f64>);

const START_UNIX_MS: u64 = 1_790_000_000_000;

fn store_rows(records: &[QueueRecord], break_at: Option<usize>) -> Vec<StoreRow> {
    records
        .iter()
        .enumerate()
        .map(|(k, &r)| (r, break_at == Some(k), (k % 2 == 0).then_some(25.5)))
        .collect()
}

fn export(rows: &[StoreRow], path: &Path) -> u64 {
    recording_file::export_db(rows.to_vec(), path, START_UNIX_MS, 1000, |_| {}).expect("exported")
}

/// The single data table of an exported file, by its `_param` partner.
fn exported_table(db: &Connection) -> String {
    let mut names = db
        .prepare("SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE '%_param'")
        .expect("names");
    let names: Vec<String> = names
        .query_map([], |r| r.get(0))
        .expect("names")
        .map(|n| n.expect("name"))
        .collect();
    assert_eq!(names.len(), 1, "{names:?}");
    names.into_iter().next().expect("a table")
}

fn is_table_name(name: &str) -> bool {
    let Some(rest) = name.strip_prefix("powerz_") else {
        return false;
    };
    let parts: Vec<&str> = rest.split('_').collect();
    parts.len() == 5
        && parts
            .iter()
            .all(|p| p.len() == 2 && p.bytes().all(|b| b.is_ascii_digit()))
}

#[test]
fn the_table_is_named_from_the_local_start_time() {
    assert_eq!(
        recording_file::db_table_name((10, 5, 9, 5, 7)),
        "powerz_10_05_09_05_07"
    );
    assert_eq!(
        recording_file::db_table_name((12, 31, 23, 59, 59)),
        "powerz_12_31_23_59_59"
    );
}

#[test]
fn an_export_writes_the_vendor_tables() {
    let dir = scratch("export-layout");
    let path = dir.join("session.db");
    let rows = store_rows(&records(10, Rate::Sps1000), None);

    assert_eq!(export(&rows, &path), 10);

    let db = Connection::open(&path).expect("database");
    let table = exported_table(&db);
    assert!(is_table_name(&table), "{table}: no serial, just the time");

    let columns = |name: &str| -> Vec<(String, String, bool)> {
        let mut q = db
            .prepare("SELECT name, type, pk FROM pragma_table_info(?1)")
            .expect("table info");
        q.query_map([name], |r| {
            Ok((
                r.get::<_, String>(0)?,
                r.get::<_, String>(1)?.to_lowercase(),
                r.get::<_, i64>(2)? != 0,
            ))
        })
        .expect("columns")
        .map(|c| c.expect("column"))
        .collect()
    };
    let data = columns(&table);
    let want = [
        "ElapsedTime",
        "Unix",
        "VBUS",
        "IBUS",
        "DP",
        "DM",
        "CC1",
        "CC2",
        "TEMP",
        "CHARGE",
        "ENERGY",
    ];
    let names: Vec<&str> = data.iter().map(|c| c.0.as_str()).collect();
    assert_eq!(names, want);
    assert_eq!(data[0].1, "text");
    assert!(data[1..].iter().all(|c| c.1 == "real"), "{data:?}");
    let keys: Vec<&str> = data.iter().filter(|c| c.2).map(|c| c.0.as_str()).collect();
    assert_eq!(keys, ["Unix"]);

    let param = columns(&format!("{table}_param"));
    let names: Vec<&str> = param.iter().map(|c| c.0.as_str()).collect();
    assert_eq!(names, ["name", "Unix", "StartTime", "SamplingRate"]);
    assert!(param.iter().all(|c| c.1 == "text"), "{param:?}");
}

#[test]
fn the_param_row_holds_the_table_the_first_unix_the_start_and_the_rate() {
    let dir = scratch("export-param");
    let path = dir.join("session.db");
    export(&store_rows(&records(10, Rate::Sps1000), None), &path);

    let db = Connection::open(&path).expect("database");
    let table = exported_table(&db);
    let (name, unix, start, rate): (String, String, String, String) = db
        .query_row(
            &format!("SELECT * FROM {}", quoted(&format!("{table}_param"))),
            [],
            |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?, r.get(3)?)),
        )
        .expect("one param row");
    assert_eq!(name, table);
    near(
        unix.parse().expect("a number"),
        START_UNIX_MS as f64 / 1000.0,
        "first Unix",
    );
    assert!(!start.trim().is_empty());
    assert_eq!(rate, "1000");
    let count: i64 = db
        .query_row(
            &format!("SELECT count(*) FROM {}", quoted(&format!("{table}_param"))),
            [],
            |r| r.get(0),
        )
        .expect("count");
    assert_eq!(count, 1);
}

