#[test]
fn rows_with_one_unix_value_are_moved_a_microsecond_apart() {
    let dir = scratch("export-same-unix");
    let path = dir.join("session.db");
    // A queue restart repeats device time: the same Unix value three times.
    let same: Vec<QueueRecord> = [100u32, 100, 100, 101]
        .iter()
        .map(|&t| QueueRecord::from_raw(t, 5_000_000, 1_000_000, [0; 4], Rate::Sps1000))
        .collect();

    assert_eq!(export(&store_rows(&same, None), &path), 4);

    let db = Connection::open(&path).expect("database");
    let table = exported_table(&db);
    let mut q = db
        .prepare(&format!(
            "SELECT Unix FROM {} ORDER BY rowid",
            quoted(&table)
        ))
        .expect("query");
    let unix: Vec<f64> = q
        .query_map([], |r| r.get(0))
        .expect("rows")
        .map(|r| r.expect("row"))
        .collect();
    assert_eq!(unix.len(), 4, "no row was lost to the primary key");
    let steps: Vec<f64> = unix.windows(2).map(|w| w[1] - w[0]).collect();
    for step in &steps[..2] {
        assert!((5e-7..1.5e-6).contains(step), "{steps:?}");
    }
    near(steps[2] + steps[1] + steps[0], 0.001, "the last row's time");
}

