// ---- AC-AXHK2S.7: a file touches no meter ----

#[test]
fn opening_a_file_needs_no_meter_and_the_module_reaches_for_none() {
    let source = include_str!("../src/recording_file.rs");
    for word in ["crate::worker", "crate::devices", "session::", "transport"] {
        assert!(!source.contains(word), "recording_file.rs names {word}");
    }
}

