    assert_same_records(&file, &records);
    let s = file.summary();
    let live = live_stats(&records, Some(2_500)).snapshot();
    assert_eq!((s.rows, s.skipped, s.left_out), (5_000, 0, 0));
    assert_eq!(s.stats.samples, live.samples);
    assert_eq!(s.stats.elapsed_ms, live.elapsed_ms);
    near_mma(s.stats.vbus, live.vbus, "VBUS");
    near_mma(s.stats.ibus, live.ibus, "IBUS");
