    let (charge, energy) = last_charge_energy(&bytes);
    assert_eq!((s.stats.charge_ah, s.stats.energy_wh), (charge, energy));
    near(s.stats.charge_ah, live.charge_ah, "charge");
    near(s.stats.energy_wh, live.energy_wh, "energy");
