/// The progress reports of an open, as `(done, total)`.
type ProgressLog = Arc<Mutex<Vec<(u64, u64)>>>;

/// Every progress report of an open, in order, with a control nothing cancels.
fn logged_control() -> (OpenControl, ProgressLog) {
    let seen: ProgressLog = Arc::default();
    let log = Arc::clone(&seen);
    let control = OpenControl {
        cancel: Arc::new(AtomicBool::new(false)),
        progress: Box::new(move |p: OpenProgress| log.lock().expect("log").push((p.done, p.total))),
    };
    (control, seen)
}

/// The names in `dir`, sorted.
fn names_in(dir: &Path) -> Vec<String> {
    let mut names: Vec<String> = std::fs::read_dir(dir)
        .expect("dir")
        .map(|e| e.expect("entry").file_name().to_string_lossy().into_owned())
        .collect();
    names.sort();
    names
}

