/// A vendor database left in WAL mode by a clean close: everything is in the
/// main file, and its header still says WAL.
fn checkpointed_wal_db(path: &Path) {
    let db = Connection::open(path).expect("database");
    db.pragma_update(None, "journal_mode", "WAL").expect("WAL");
    create_vendor_tables(&db, TABLE);
    insert_rows(&db, TABLE, &three_rows());
    db.query_row("PRAGMA wal_checkpoint(TRUNCATE)", [], |_| Ok(()))
        .expect("checkpoint");
    drop(db);
    assert_eq!(std::fs::read(path).expect("file")[18], 2, "not a WAL file");
}

#[test]
fn a_checkpointed_wal_database_opens_and_leaves_nothing_beside_it() {
    let dir = scratch("db-wal");
    let path = dir.join("run.db");
    checkpointed_wal_db(&path);
    assert_eq!(names_in(&dir), ["run.db"]);
    let before = std::fs::read(&path).expect("file");

    let s = opened(recording_file::open_db(&path, &mut silent())).summary();

    assert_eq!(s.rows, 3);
    assert_eq!(names_in(&dir), ["run.db"], "no -wal or -shm stays behind");
    assert_eq!(std::fs::read(&path).expect("file"), before);
}

#[test]
fn a_path_with_uri_characters_opens_as_a_database() {
    // Windows forbids '?' in a file name, so there the name carries the URI
    // characters Windows allows: '%', '#', a space, '&' and '='.
    #[cfg(not(windows))]
    const NAME: &str = "100% a#b?c.db";
    #[cfg(windows)]
    const NAME: &str = "100% a#b&c=d.db";
    let dir = scratch("db-uri-path");
    let path = dir.join(NAME);
    vendor_db(&path, TABLE, &three_rows());
    let s = opened(recording_file::open_db(&path, &mut silent())).summary();
    assert_eq!(s.rows, 3);
    assert_eq!(names_in(&dir), [NAME]);
}

