#[test]
fn a_table_without_rowids_opens_with_an_unknown_total() {
    let dir = scratch("db-without-rowid");
    let path = dir.join("run.db");
    let rows: Vec<DbRow> = (0..10_000).map(|k| db_row(k, 5.0, 0.0, 0.0)).collect();
    {
        let mut db = Connection::open(&path).expect("database");
        db.execute_batch(&format!(
            "CREATE TABLE {TABLE}({DATA_COLUMNS}) WITHOUT ROWID;
             CREATE TABLE {TABLE}_param({PARAM_COLUMNS});"
        ))
        .expect("tables");
        let tx = db.transaction().expect("transaction");
        insert_rows(&tx, TABLE, &rows);
        tx.commit().expect("commit");
    }
    let (mut control, seen) = logged_control();

    let s = opened(recording_file::open_db(&path, &mut control)).summary();

    assert_eq!(s.rows, 10_000);
    let seen = seen.lock().expect("log");
    assert!(seen.iter().all(|&(_, total)| total == 0), "{seen:?}");
    assert!(seen.is_sorted_by_key(|p| p.0), "{seen:?}");
    assert_eq!(seen.last().expect("a report").0, 10_000, "{seen:?}");
}

