/// How many times the rate changes along `file`, which is what its history
/// keeps one entry for.
fn rate_changes(file: &OpenedFile) -> usize {
    let rates: Vec<Rate> = file.records().iter().map(|r| r.rate()).collect();
    rates.windows(2).filter(|w| w[0] != w[1]).count()
}

/// A row at `ms` with `cc1` volts on CC1.
fn row_with_cc1(ms: u64, cc1: f64) -> String {
    format!("{},,5,1,0.6,0.01,{cc1},0.002,,,,", format_elapsed(ms))
}

#[test]
fn a_file_changes_its_line_scale_at_most_once() {
    let dir = scratch("csv-alternating");
    // Each second row is past the fine scale: 2,000 changes at one per row.
    let rows: Vec<String> = (0..2_000)
        .map(|k| row_with_cc1(k, if k % 2 == 0 { 1.5 } else { 7.5 }))
        .collect();
    let path = write_csv(&dir, "run.csv", &rows);

    let file = opened(recording_file::open_csv(&path, &mut silent()));

    assert_eq!(rate_changes(&file), 1);
    let got: Vec<f64> = file.records().iter().map(|r| r.cc1_v()).collect();
    for (k, v) in got.iter().enumerate() {
        near(*v, if k % 2 == 0 { 1.5 } else { 7.5 }, "CC1");
    }
}

#[test]
fn a_line_scale_change_lands_on_the_first_row_that_needs_it_and_stays() {
    let dir = scratch("csv-one-switch");
    let path = write_csv(
        &dir,
        "run.csv",
        &[
            row_with_cc1(0, 1.2345),
            row_with_cc1(1, 7.5),
            row_with_cc1(2, 1.2345),
        ],
    );
    let file = opened(recording_file::open_csv(&path, &mut silent()));
    let got: Vec<(Rate, f64)> = file
        .records()
        .iter()
        .map(|r| (r.rate(), r.cc1_v()))
        .collect();
    assert_eq!(got[0].0, Rate::Sps2);
    near(got[0].1, 1.2345, "fine");
    assert_eq!(got[1].0, Rate::Sps1000);
    assert_eq!(got[2].0, Rate::Sps1000, "the rest of the file stays coarse");
}

#[test]
